-- Back exercises that need only the floor. Without them a plan with no equipment ("Keine
-- Geräte") had nothing to pull with, so its back went untrained. Strength standards in reps, as
-- for the other bodyweight exercises.
insert into public.exercises
  (id, name, instructions, equipment, measures, muscles, rest_seconds, strength_standard)
values
  ('prone-y-raise', '{"en":"Prone Y Raise","de":"Y-Heben in Bauchlage","pt-PT":"Elevação Y deitado","pt-BR":"Elevação Y de bruços","ko":"엎드려 Y 레이즈"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down with your arms stretched overhead in a Y, thumbs pointing up. Rest your forehead on a folded towel."},{"title":"Lift","text":"Pull your shoulder blades back and down and lift your arms off the floor as high as you can without arching your lower back. Hold for 1–2 seconds."},{"title":"Lower","text":"Lower your arms slowly and relax briefly before the next rep."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Bauch, die Arme schräg nach vorne zu einem Y gestreckt, die Daumen zeigen nach oben. Leg die Stirn auf ein gefaltetes Handtuch."},{"title":"Abheben","text":"Zieh die Schulterblätter nach hinten unten und heb die Arme so hoch wie möglich vom Boden ab, ohne ins Hohlkreuz zu gehen. Halte 1–2 Sekunden."},{"title":"Ablegen","text":"Senk die Arme langsam ab und entspann kurz vor der nächsten Wiederholung."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo, com os braços esticados à frente em Y e os polegares para cima. Apoia a testa numa toalha dobrada."},{"title":"Elevar","text":"Puxa as omoplatas para trás e para baixo e levanta os braços do chão o mais alto que conseguires, sem arquear a zona lombar. Mantém 1–2 segundos."},{"title":"Descida","text":"Baixa os braços devagar e relaxa um instante antes da repetição seguinte."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços, com os braços estendidos à frente em Y e os polegares para cima. Apoie a testa em uma toalha dobrada."},{"title":"Elevar","text":"Puxe as escápulas para trás e para baixo e tire os braços do chão o mais alto que conseguir, sem arquear a lombar. Segure por 1–2 segundos."},{"title":"Descida","text":"Abaixe os braços devagar e relaxe por um instante antes da próxima repetição."}],"ko":[{"title":"준비","text":"엎드려서 팔을 Y자로 앞쪽 위로 뻗고 엄지가 위를 향하게 해요. 이마는 접은 수건 위에 둬요."},{"title":"들어 올리기","text":"견갑골을 뒤아래로 당기며 허리를 꺾지 않는 범위에서 팔을 최대한 높이 들어 올려요. 1–2초 버텨요."},{"title":"내리기","text":"팔을 천천히 내리고 다음 반복 전에 잠깐 힘을 빼요."}]}'::jsonb,
    'bodyweight', '{reps}', '{"upper_back":0.4,"traps":0.35,"rear_delts":0.25}'::jsonb, 45, 15),
  ('prone-t-raise', '{"en":"Prone T Raise","de":"T-Heben in Bauchlage","pt-PT":"Elevação T deitado","pt-BR":"Elevação T de bruços","ko":"엎드려 T 레이즈"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down with your arms out to the sides in a T, thumbs pointing up."},{"title":"Lift","text":"Squeeze your shoulder blades together and lift your arms off the floor. Keep your neck long and your eyes on the floor. Hold for 1–2 seconds."},{"title":"Lower","text":"Lower your arms slowly and relax briefly."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Bauch, die Arme seitlich zu einem T ausgestreckt, die Daumen zeigen nach oben."},{"title":"Abheben","text":"Zieh die Schulterblätter zusammen und heb die Arme vom Boden ab. Halte den Nacken lang und den Blick zum Boden. Halte 1–2 Sekunden."},{"title":"Ablegen","text":"Senk die Arme langsam ab und entspann kurz."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo, com os braços abertos para os lados em T e os polegares para cima."},{"title":"Elevar","text":"Aperta as omoplatas uma contra a outra e levanta os braços do chão. Mantém o pescoço alongado e o olhar no chão. Mantém 1–2 segundos."},{"title":"Descida","text":"Baixa os braços devagar e relaxa um instante."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços, com os braços abertos para os lados em T e os polegares para cima."},{"title":"Elevar","text":"Aperte as escápulas uma contra a outra e tire os braços do chão. Mantenha o pescoço alongado e o olhar no chão. Segure por 1–2 segundos."},{"title":"Descida","text":"Abaixe os braços devagar e relaxe por um instante."}],"ko":[{"title":"준비","text":"엎드려서 팔을 옆으로 T자로 벌리고 엄지가 위를 향하게 해요."},{"title":"들어 올리기","text":"견갑골을 모으며 팔을 바닥에서 들어 올려요. 목은 길게, 시선은 바닥을 향해요. 1–2초 버텨요."},{"title":"내리기","text":"팔을 천천히 내리고 잠깐 힘을 빼요."}]}'::jsonb,
    'bodyweight', '{reps}', '{"upper_back":0.5,"rear_delts":0.35,"traps":0.15}'::jsonb, 45, 15),
  ('reverse-snow-angel', '{"en":"Reverse Snow Angel","de":"Umgekehrter Schneeengel","pt-PT":"Anjo de neve invertido","pt-BR":"Anjo de neve invertido","ko":"리버스 스노우 엔젤"}'::jsonb,
    '{"en":[{"title":"Set up","text":"Lie face down with your arms by your sides, palms down, and lift your hands and chest slightly off the floor."},{"title":"Sweep","text":"Keeping your arms straight and off the floor, sweep them out to the sides and over your head in a wide arc."},{"title":"Return","text":"Sweep them back the same way to your hips, squeezing your shoulder blades together. That''s one rep."}],"de":[{"title":"Aufbauen","text":"Leg dich auf den Bauch, die Arme neben dem Körper, die Handflächen nach unten. Heb Hände und Brust leicht vom Boden ab."},{"title":"Bogen","text":"Führ die gestreckten Arme knapp über dem Boden in einem weiten Bogen seitlich bis über den Kopf."},{"title":"Zurück","text":"Führ sie auf demselben Weg zurück zur Hüfte und zieh dabei die Schulterblätter zusammen. Das ist eine Wiederholung."}],"pt-PT":[{"title":"Preparação","text":"Deita-te de barriga para baixo, com os braços ao lado do corpo e as palmas para baixo. Levanta ligeiramente as mãos e o peito do chão."},{"title":"Arco","text":"Com os braços esticados e afastados do chão, leva-os para os lados e por cima da cabeça num arco amplo."},{"title":"Regresso","text":"Volta pelo mesmo caminho até às ancas, apertando as omoplatas. Isto é uma repetição."}],"pt-BR":[{"title":"Preparação","text":"Deite de bruços, com os braços ao lado do corpo e as palmas para baixo. Tire as mãos e o peito levemente do chão."},{"title":"Arco","text":"Com os braços estendidos e fora do chão, leve-os para os lados e por cima da cabeça em um arco amplo."},{"title":"Volta","text":"Volte pelo mesmo caminho até o quadril, apertando as escápulas. Isso é uma repetição."}],"ko":[{"title":"준비","text":"엎드려서 팔을 몸 옆에 두고 손바닥이 아래를 향하게 해요. 손과 가슴을 바닥에서 살짝 들어요."},{"title":"원 그리기","text":"팔을 편 채 바닥에 닿지 않게 옆으로 크게 원을 그리며 머리 위까지 보내요."},{"title":"되돌리기","text":"같은 길로 엉덩이 옆까지 되돌리며 견갑골을 모아요. 이게 1회예요."}]}'::jsonb,
    'bodyweight', '{reps}', '{"lats":0.35,"upper_back":0.35,"rear_delts":0.2,"traps":0.1}'::jsonb, 45, 12);
